(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zs-sj-prepa-ssrpf-j4-sfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zs-sj-prepa-ssrpf-j4-sfm\",\n \"titre\": \"Préparation D.E (J) · J4 SSR/PF SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 55,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n   \"sha256\": \"9ee0174cae6a310ff499e14b7685289c3bf3a2155e497e3971a6b1d18f45aa2e\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J SSR / PF · Prépa D.E J4 (SFM) · J4 et J10 identiques\",\n     \"slug\": \"prepa-ssrpf-j4-sfm\",\n     \"pages\": \"\",\n     \"count\": 55,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"SSR / PF\",\n     \"source\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente allaite exclusivement son nouveau-né âgé de 18 jours. Elle souhaite débuter une contraception oestro-progestative combinée car elle craint les autres méthodes. A ce stade l'OMS? Préconise la catégorie 3\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez la femme allaitante à moins de 6 semaines (42 jours) du post-partum (ici 18 jours), les contraceptifs œstro-progestatifs combinés (COC) sont classés en catégorie 4 (contre-indication absolue) selon les critères d'éligibilité médicale de l'OMS, et non en catégorie 3, car les œstrogènes altèrent la sécrétion lactée.\\n\\nSource : Cours SR/PF L2 — Chap. 4 & 12 : Critères médicaux d'éligibilité de l'OMS des CHC.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les pilules de quatrième génération contiennent du DIENOGEST\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les contraceptifs oraux combinés de quatrième génération associent un œstrogène à des progestatifs de synthèse récents tels que le diénogest, la drospirénone, le nomégestrol ou la chlormadinone.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Contraceptifs hormonaux combinés (CHC).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle de génération des contraceptifs hormonaux combinés selon le type de progestérone utilisée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les différentes générations (1re, 2e, 3e et 4e générations) des contraceptifs hormonaux combinés sont définies en fonction de la molécule progestative (progestérone de synthèse) associée à l'éthinylestradiol ou à l'estradiol.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Contraceptifs hormonaux combinés (CHC).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le préservatif, la cape cervicale, le spermicide et le diaphragme sont des méthodes de barrières\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les méthodes contraceptives de barrière bloquent physiquement ou chimiquement l'ascension des spermatozoïdes vers l'utérus ; elles comprennent les barrières mécaniques (préservatifs masculin et féminin, diaphragme, cape cervicale) et les barrières chimiques (spermicides).\\n\\nSource : Cours SR/PF L2 — Chap. 11 : Méthodes de barrière (p. 40).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La palpation du sein se fait en position couchée, le bras du sein examiné replié sur la tête\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lors de l'examen clinique des seins en consultation de planification familiale, la palpation s'effectue chez la cliente allongée sur le dos (décubitus dorsal) avec le bras du côté examiné replié sur/sous la tête afin d'étaler uniformément la glande mammaire sur le gril costal.\\n\\nSource : Cours SR/PF L2 — Chap. 7 : Consultation en planification familiale (examen des seins).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme KY désire avoir des rapports sexuels non protégés avec son conjoint après la pose d'implant. Alors, elle ne doit pas attendre 24 heures pour tout rapport sexuel après la pose\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lorsque l'implant contraceptif sous-cutané est posé dans les conditions requises (dans les 7 premiers jours du cycle menstruel ou en relais direct d'une contraception hormonale active), son efficacité contraceptive est immédiate, sans nécessité d'attendre 24 heures avant d'avoir des rapports sexuels.\\n\\nSource : Cours SR/PF L2 — Chap. 13 : Contraceptifs hormonaux progestatifs (implants).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le counseling se définit comme étant un entretien, une tête à tête qui a lieu dans un endroit calme au cours duquel une personne aide une autre personne à trouver et choisir une solution à son problème\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « F » car cette formulation générale omet les spécificités du counseling en planification familiale (communication interpersonnelle interactive entre un prestataire qualifié et un client pour l'aider à prendre une décision libre et éclairée en matière de contraception ou de santé reproductive).\\n\\nSource : Cours SR/PF L2 — Chap. 6 : Counseling en planification familiale (p. 21).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La consultation en planification familiale est le processus par lequel un prestataire de services de planification familiale interagit avec un client pour choisir et utiliser une méthode contraceptive ou pour trouver une solution à un problème de santé sexuelle\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon le cours SR/PF (chap. 7, p. 25), cette définition s'applique au processus relationnel d'aide (« trouver une solution à un problème de santé de la reproduction » / counseling), alors que la consultation de PF englobe également l'anamnèse complète, l'examen général, physique et gynécologique ainsi que l'application des critères médicaux d'éligibilité.\\n\\nSource : Cours SR/PF L2 — Chap. 7 : Consultation en planification familiale (p. 25).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme RIA Sage-femme réfère une cliente qui présente un avortement provoqué septique avec un désir de contraception le DIU\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'avortement septique constitue une contre-indication absolue (catégorie 4 de l'OMS) à la pose immédiate d'un DIU en raison du risque d'aggravation de l'infection utérine et pelvienne ; la sage-femme doit référer la cliente pour prise en charge médicale de l'infection avant d'envisager ultérieurement la pose du DIU après guérison complète.\\n\\nSource : Cours SR/PF L2 — Chap. 14 & 17 : DIU et contraception du post-abortum.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'examen des seins se fait méthodiquement quadrant par quadrant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'inspection et la palpation des deux seins doivent se pratiquer avec méthode, quadrant par quadrant (supéro-externe, inféro-externe, inféro-interne, supéro-interne), complétées par la recherche d'un écoulement mamelonnaire et la palpation des aires ganglionnaires axillaires et sus-claviculaires.\\n\\nSource : Cours SR/PF L2 — Chap. 7 : Examen clinique des seins en consultation de PF.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les autres antécédents sont constitués des antécédents gynécologiques, obstétricaux et familiaux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans la fiche individuelle de consultation en PF, les antécédents gynécologiques, obstétricaux et familiaux constituent des rubriques majeures et distinctes de l'anamnèse ; les « autres antécédents » regroupent le mode de vie (tabac, alcool), les allergies et les traitements en cours.\\n\\nSource : Cours SR/PF L2 — Chap. 7 & Annexe 3 : Fiche individuelle de consultation en PF.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échographie est indiquée lorsque survient une infection après la pose d'un DIU\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant une infection génitale haute survenant après la pose d'un DIU, la conduite repose sur le diagnostic clinique, les prélèvements bactériologiques et l'antibiothérapie (avec retrait du DIU si absence d'amélioration sous 48-72 h) ; l'échographie pelvienne est indiquée lorsque les fils du DIU sont introuvables au spéculum ou en cas de suspicion de grossesse sur DIU.\\n\\nSource : Cours SR/PF L2 — Chap. 14 : Dispositif intra-utérin (DIU) et gestion des complications (p. 85).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente oublie deux pilules oestro-progestatives consécutives (jours dix huit et dix neuf de sa plaquette de vingt un comprimés). Elle a eu un rapport non protégé au seizième jour du cycle. il faut jeter les comprimés restants de la période d'arrêt et enchaîner sans pause\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En cas d'oubli de 2 comprimés actifs ou plus au cours de la 3e semaine (jours 15 à 21) d'une plaquette de COC, la patiente doit prendre immédiatement le dernier comprimé oublié, achever les comprimés actifs restants de la plaquette en cours puis enchaîner directement une nouvelle plaquette sans observer la pause habituelle de 7 jours (ou en jetant les comprimés inactifs).\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Gestion des oublis de contraceptifs oraux combinés.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le DIU entraine les infections\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le stérilet (DIU) en soi ne crée pas d'infection pelvienne : le faible risque infectieux observé dans les 20 premiers jours suivant la pose provient uniquement de l'introduction ascendante de germes cervicaux préexistants (IST non dépistée) ou d'une faute d'asepsie lors de l'insertion.\\n\\nSource : Cours SR/PF L2 — Chap. 14 : Dispositif intra-utérin (DIU) : rumeurs et prévention des infections.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pose du DIU est indiquée si à l'examen vous constatez un col sain\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'examen au spéculum avant l'insertion d'un DIU permet de vérifier que le col utérin est sain (absence de cervicite purulente, d'ulcération ou de lésion suspecte de cancer du col) ; un col sain autorise la pose du DIU après vérification de l'absence de grossesse.\\n\\nSource : Cours SR/PF L2 — Chap. 14 : Examen gynécologique et insertion du DIU.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le premier volet de la fiche de référence et contre référence est rempli par le médecin\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le premier volet (bulletin de référence) est rempli par l'agent de santé périphérique (sage-femme, maïeuticien ou infirmier) qui adresse la cliente vers le centre de référence ; le médecin du centre d'accueil remplit le volet de contre-référence après la prise en charge.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 31 : Organisation de la référence et contre-référence (p. 125). SUJET 2 : QCM (Questions à Choix Multiple)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En quoi consiste principalement une approche « transformatrice de genre » appliquée à la GHM en milieu scolaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réserver l'enseignement de l'hygiène menstruelle exclusivement aux enseignants de mathématiques.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Déconstruire les tabous culturels en éduquant l'ensemble de la communauté scolaire.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Interdire strictement aux élèves de prononcer le mot « règles » dans l'enceinte de l'établissement.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Limiter l'accès aux toilettes propres uniquement aux élèves ayant les meilleures notes académiques.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Déconstruire les tabous culturels en éduquant l'ensemble de la communauté scolaire.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'approche transformatrice de genre appliquée à la gestion de l'hygiène menstruelle (GHM) en milieu scolaire vise à briser les normes et tabous socioculturels autour des menstruations en sensibilisant et en impliquant tous les acteurs de l'école (filles, garçons, enseignants et personnel éducatif).\\n\\nSource : Cours SR/PF L2 — Chap. 17 : Santé sexuelle et reproductive des adolescents et approche genre.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher le principe de base du counseling chez le client\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La liberté de la méthode contraceptive\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La liberté de s'éclairé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le consentement exprimé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les droits du client\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Le consentement exprimé\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le principe fondamental du counseling du côté du client réside dans son autonomie décisionnelle et son consentement librement et clairement exprimé après avoir compris les informations reçues.\\n\\nSource : Cours SR/PF L2 — Chap. 6 : Counseling en planification familiale (p. 21).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente de 29 ans fait retirer son implant à l'étonogestrel car elle souhaite planifier une grossesse avec son conjoint. Elle s'inquiète du temps nécessaire pour retrouver une fertilité normale. Que lui indiquez-vous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"6 à 12 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Immédiat\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2ans\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"3 cycles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Immédiat\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après le retrait d'un implant sous-cutané (Implanon NXT à l'étonogestrel ou Jadelle au lévonorgestrel), l'élimination de l'hormone est rapide et le retour à la fertilité est immédiat (sans délai de latence, contrairement aux injectables progestatifs).\\n\\nSource : Cours SR/PF L2 — Chap. 13 : Contraceptifs hormonaux progestatifs (implants).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher le principe de base du counseling chez le prestataire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La maîtrise du débat\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le fait de tirer les leçons de l'exemple\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Demeurer positif, constructif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'éducation du passé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Demeurer positif, constructif\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Chez le prestataire, l'attitude professionnelle de base en counseling consiste à adopter une écoute active, bienveillante et respectueuse, en demeurant positif et constructif sans jamais juger ni imposer un choix au client.\\n\\nSource : Cours SR/PF L2 — Chap. 6 : Principes et qualités du conseiller en PF.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle affirmation concernant la contraception d'urgence hormonale chez l'adolescente est exacte ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elle peut remplacer une contraception régulière et être utilisée toutes les semaines sans risque.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Elle nécessite obligatoirement une prescription médicale préalable par un spécialiste.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elle provoque systématiquement une interruption médicale de grossesse en cas d'œuf déjà implanté.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Elle doit être administrée le plus tôt possible après le rapport non protégé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Elle doit être administrée le plus tôt possible après le rapport non protégé\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'efficacité de la contraception d'urgence hormonale (pilules contraceptives d'urgence) décroît avec le temps écoulé depuis le rapport sexuel non protégé : elle doit donc être prise le plus précocement possible (idéalement dans les 24 premières heures et jusqu'à 72-120 heures). Elle n'est pas abortive et ne doit pas se substituer à une contraception régulière.\\n\\nSource : Cours SR/PF L2 — Chap. 17 : Contraception d'urgence et contraception des adolescents.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Nommer la phase du counseling où toutes les méthodes sont décrites\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Counseling initial\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Counseling spécifique à la méthode\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Counseling de suivi\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Counseling initial\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le counseling initial (ou général) consiste à présenter brièvement l'ensemble des méthodes contraceptives disponibles afin d'aider la cliente à faire un choix éclairé, avant de passer au counseling spécifique portant uniquement sur la méthode retenue.\\n\\nSource : Cours SR/PF L2 — Chap. 6 : Les trois phases du counseling en PF (p. 21).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher les deux étapes du counseling qui se suivent\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rendez-vous\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Choix de méthode\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Renseignements\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Explication\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Choix de méthode ; C. Renseignements\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Dans la démarche en 6 étapes du counseling selon l'acronyme BERCER (Bienvenue, Entretien, Renseignements, Choix de la méthode, Explication, Rendez-vous), l'étape « Renseignements » précède immédiatement l'étape « Choix de la méthode ».\\n\\nSource : Cours SR/PF L2 — Chap. 6 : Les étapes du counseling (approche BERCER).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente de 39 ans, en bonne santé par ailleurs, souhaite débuter une pilule oestro-progestative combinée. Elle fume activement 18 cigarettes par jour depuis l'âge de vingt ans. Quelle est la conduite à tenir selon l'OMS ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prescription possible sous surveillance tensionnelle rapprochée.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prescription autorisée si la patiente s'engage à réduire sa consommation de moitié.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Contre-indication absolue.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Utilisation sans restriction.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Contre-indication absolue.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Selon les critères d'éligibilité médicale de l'OMS (et l'annexe 3 du cours SR/PF), l'association d'un âge ≥ 35 ans (39 ans) et d'un tabagisme important (≥ 15 cigarettes/jour, ici 18 cigarettes/jour) classe les contraceptifs œstro-progestatifs combinés en catégorie 4 (contre-indication absolue) en raison du risque thromboembolique et cardiovasculaire majeur.\\n\\nSource : Cours SR/PF L2 — Chap. 4 & Annexe 3 : Critères d'éligibilité médicale de l'OMS (CHC).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher le but de la consultation en planification familiale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ne pas s'assurer que la cliente est enceinte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dépister les infections sexuelles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Identifier les indications médicales\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Identifier les indications médicales\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La consultation de planification familiale a pour objectif principal d'évaluer l'éligibilité clinique de la cliente afin d'identifier les indications et contre-indications médicales aux différentes méthodes contraceptives (tout en s'assurant de l'absence de grossesse).\\n\\nSource : Cours SR/PF L2 — Chap. 7 : Buts de la consultation d'une cliente en PF (p. 25).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il existe combien de groupes de contraceptifs hormonaux combinés\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"03\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"04\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"10\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"14\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 04\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les contraceptifs hormonaux combinés (CHC) se répartissent en 04 groupes selon leur voie d'administration : les contraceptifs oraux combinés (COC), les contraceptifs injectables combinés (CIC), le patch contraceptif transdermique et l'anneau vaginal combiné.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Contraceptifs hormonaux combinés (CHC) (p. 47).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme GRO est sous contraceptif injectable contenant deux types d'hormones. Cocher le prochain rendez-vous\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rendez-vous dans quatre semaines\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rendez-vous dans huit semaines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rendez-vous dans douze semaines\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Rendez-vous dans quatre semaines\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un contraceptif injectable contenant deux hormones (œstrogène + progestatif) est un contraceptif injectable combiné (CIC), qui s'administre tous les mois : le prochain rendez-vous est donc fixé à quatre semaines (contrairement au Noristérat à 8 semaines et au Depo-Provera à 12 semaines).\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Les contraceptifs injectables combinés (CIC).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher l'élément de l'identité du client dans la consultation en planification familiale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Age en mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Niveau d'éducation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fonction\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Fonction\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans l'observation clinique de planification familiale, la rubrique « Identité » recense le nom, les prénoms, l'âge (en années), la profession/fonction, le domicile et la situation matrimoniale du client.\\n\\nSource : Cours SR/PF L2 — Chap. 7 : Les étapes de la consultation en planification familiale.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une patiente de 32 ans, tabagique sevrée, consulte pour une contraception hormonale combinée. Elle présente des migraines avec aura survenant deux fois par mois. Selon les critères d'éligibilité médicale de l'OMS, quelle est la classification de la CHC pour cette patiente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Catégorie 1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Catégorie 2\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Catégorie 4\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Catégorie 3\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Catégorie 4\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La présence de migraines avec aura (signes neurologiques focaux précédant la céphalée) constitue, à tout âge, une contre-indication absolue (Catégorie 4 de l'OMS) aux contraceptifs hormonaux combinés (CHC) en raison du risque élevé d'accident vasculaire cérébral ischémique.\\n\\nSource : Cours SR/PF L2 — Chap. 4 & 12 : Critères médicaux d'éligibilité de l'OMS (CHC).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La méthode contraceptive spécifique pour l'adolescent est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"MAMA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Condom\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Méthode chirurgicale volontaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Condom\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez l'adolescent(e) sexuellement actif(ve), particulièrement exposé(e) au risque d'IST/VIH et de grossesses précoces, le préservatif (condom) est la méthode de choix recommandée car il assure la double protection. La stérilisation chirurgicale n'est pas adaptée et la MAMA ne concerne que la femme allaitante en post-partum.\\n\\nSource : Cours SR/PF L2 — Chap. 17 : La contraception des adolescents (p. 125).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher l'élément qui figure sur la fiche de référence et contre référence\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La date\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le nom et la signature\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La conduite à tenir infirmière\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Le nom et la signature\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La fiche de référence et contre-référence doit obligatoirement porter le nom, les prénoms, la qualité et la signature du prestataire ayant effectué la référence ou la contre-référence afin de valider le document médical.\\n\\nSource : Cours de Gynéco-Obstétrique L3 — Chap. 31 : Fiche de référence et contre-référence (p. 125).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__31\",\n       \"num\": \"32\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : Une utilisatrice d'une pilule oestro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"Quelle est la conduite immédiate à tenir ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prendre immédiatement la pilule oubliée.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Jeter la plaquette en cours et recommencer un nouveau cycle immédiatement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Ne rien faire de particulier\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Attendre les prochaines règles.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Prendre immédiatement la pilule oubliée.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Face à un oubli de plus de 12 heures (ici 36 heures) au 3e jour de la plaquette, le premier geste consiste à prendre immédiatement le comprimé oublié dès la constatation de l'oubli (en plus du comprimé du jour à l'heure habituelle).\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Conduite à tenir devant un oubli de COC.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__32\",\n       \"num\": \"33\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : Une utilisatrice d'une pilule oestro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"Doit-elle continuer la plaquette ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Après avoir pris le comprimé oublié, la cliente doit poursuivre normalement la prise d'un comprimé par jour jusqu'à la fin de sa plaquette.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Conduite à tenir devant un oubli de COC.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__33\",\n       \"num\": \"34\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : Une utilisatrice d'une pilule oestro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"Doit elle utiliser une contraception d'urgence ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Comme l'oubli (> 12 heures) a lieu durant la 1re semaine de la plaquette (J3) et qu'un rapport sexuel non protégé est survenu dans les 5 jours précédant l'oubli (48 heures avant), il existe un risque de fécondation justifiant la prise d'une contraception d'urgence.\\n\\nSource : Cours SR/PF L2 — Chap. 12 & 17 : Oubli de pilule en 1re semaine et contraception d'urgence.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__34\",\n       \"num\": \"35\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"ETUDE DE CAS : Une utilisatrice d'une pilule oestro-progestative monophasique oublie de prendre sa pilule du troisième jour de sa plaquette. Elle s'en aperçoit trente six heures plus tard (au moment de prendre la pilule suivante). Elle a eu un rapport sexuel non protégé 48 heures avant l'oubli.\",\n       \"text\": \"En cas de rapports sexuelles doit elle se protégée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La suppression ovarienne étant fragilisée par cet oubli de 36 heures en début de cycle, la cliente doit impérativement utiliser une méthode barrière (préservatif) ou observer l'abstinence pendant les 7 jours qui suivent la reprise régulière des comprimés.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Oubli de pilule combinée et méthode d'appoint.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une utilisatrice sous COC qui présente des spottings après trois cycles doit être :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Examiner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Examiner\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les petits saignements intermenstruels (spottings) sont fréquents et bénins au cours des 3 premiers cycles d'utilisation d'un COC (on rassure) ; au-delà de trois cycles, leur persistance impose d'examiner la cliente (interrogatoire sur l'observance et examen gynécologique/au spéculum) pour éliminer une cause organique ou infectieuse.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Gestion des effets secondaires des COC (saignements irréguliers).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'examen gynécologique anormal chez une cliente sous contraception hormonale. Il faut\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Consultation prénatale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Référer\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Conformément aux algorithmes décisionnels du suivi en planification familiale (Annexe du cours SR/PF), la mise en évidence d'une anomalie à l'examen gynécologique (lésion cervicale, masse annexielle ou utérine, saignement inexpliqué) impose de référer la cliente vers un médecin spécialiste.\\n\\nSource : Cours SR/PF L2 — Algorithme de suivi clinique en planification familiale.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant la présence d'autres signes de grossesse chez une cliente après la troisième plaquette\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Examiner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Examiner\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Lorsqu'une utilisatrice de pilule présente des signes cliniques évoquant une grossesse (nausées, vomissements, tension mammaire, retard de règles), il faut l'examiner et pratiquer un test de grossesse pour confirmer ou infirmer le diagnostic.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Suivi des utilisatrices de contraceptifs oraux combinés.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le STEDIRIL contient\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"35 microgrammes EE\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"50 microgrammes EE\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"100 microgrammes EE\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 50 microgrammes EE\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le Stédiril® est un contraceptif oral combiné normodosé contenant 50 microgrammes (0,05 mg) d'éthinylestradiol (EE) associés à 0,5 mg de norgestrel.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Classification et dosages des COC.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente sous pilule oestro-progestative souhaite passer à un implant sous-cutané. Elle a pris sa dernière pilule active hier et souhaite se faire poser l'implant aujourd'hui.\",\n       \"text\": \"Le prestataire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La rassure.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Lui dit d'attendre les règles.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elle doit revenir dans sept jours.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Elle utilise une protection par préservatif.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La rassure.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Elle prenait correctement sa pilule : elle est protégée et l'implant peut être posé tout de suite, sans attendre les règles ni utiliser de méthode d'appoint. On la rassure.\\n\\nSource : Document SSR L2 SF (cours SR/PF, INFAS), chapitre « Contraceptifs hormonaux progestatifs » (moment d'administration) ; partiellement hors cours\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente sous pilule oestro-progestative souhaite passer à un implant sous-cutané. Elle a pris sa dernière pilule active hier et souhaite se faire poser l'implant aujourd'hui.\",\n       \"text\": \"La patiente est-elle protégée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'insertion immédiate en relais d'un comprimé actif pris la veille évite toute rupture de couverture hormonale ; la patiente est donc protégée sans interruption.\\n\\nSource : Cours SR/PF L2 — Chap. 13 : Relais contraceptif vers l'implant sous-cutané.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente sous pilule oestro-progestative souhaite passer à un implant sous-cutané. Elle a pris sa dernière pilule active hier et souhaite se faire poser l'implant aujourd'hui.\",\n       \"text\": \"Le prestataire doit-il insérer l'implant ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"OUI\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. OUI\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'absence de grossesse étant raisonnablement établie grâce à la prise régulière de la pilule active jusqu'à la veille, le prestataire doit insérer l'implant dès cette consultation.\\n\\nSource : Cours SR/PF L2 — Chap. 13 : Moment d'insertion des implants contraceptifs.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme HI a opté le 01 janvier 2025 pour les Comprimés combinés. Elle a oublié la prise du 01 mars et a néanmoins continué sa méthode\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Protégée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Non protégée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Référer\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Protégée\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon les normes de gestion des oublis de COC enseignées en SR/PF, l'oubli isolé d'une seule pilule combinée suivi de la reprise et de la poursuite normale de la plaquette n'annule pas l'efficacité contraceptive : la cliente demeure protégée.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Gestion d'un oubli isolé de COC.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme HI exige les préservatifs pendant les rapports sexuels avec son conjoint\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Normal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Anormal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Anormal\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient « Anormal » car, dans ce cas clinique où la cliente utilise correctement sa pilule combinée (un seul oubli isolé) sans facteur de risque d'IST mentionné, une méthode d'appoint par préservatif n'est pas médicalement requise pour l'efficacité contraceptive.\\n\\nSource : Cours SR/PF L2 — Chap. 12 : Suivi sous contraceptifs oraux combinés.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"29 mars 2025 Mme HI est sous contraceptif injectable progestatif. Car, elle a des migraines\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La décision est normale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La décision est anormale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La décision n'est pas rassurante\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La décision est normale\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les migraines contre-indiquent les contraceptifs contenant des œstrogènes (risque vasculaire cérébral), tandis que les contraceptifs injectables progestatifs seuls (CIP) sont autorisés chez la femme migraineuse ; ce changement de méthode est donc parfaitement normal.\\n\\nSource : Cours SR/PF L2 — Chap. 4 & 13 : Critères d'éligibilité médicale des CIP (migraines).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"07 juin 2025, Mme HI opte pour les Comprimés. Car, elle a manifesté une rougeur au point d'injection. La PI est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Accompli\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rigoureuse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Partielle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Option 2\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Partielle\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une réaction locale bénigne au point d'injection (rougeur) relève d'un simple counseling rassurant et ne nécessite pas d'abandonner la méthode ni de revenir vers des comprimés contre-indiqués par ses migraines ; cela traduit une prise en charge/information (PI) partielle. Remarque : une option vide résiduelle (« Option 2 ») apparaît dans le sujet.\\n\\nSource : Cours SR/PF L2 — Chap. 13 : Gestion des effets secondaires des contraceptifs injectables.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme HI peut utiliser en 2026\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contraception chirurgical volontaire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"MAMA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dispositif intra utérin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Dispositif intra utérin\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le dispositif intra-utérin (DIU) au cuivre constitue une méthode contraceptive réversible de longue durée dépourvue d'hormones (parfaitement compatible avec ses antécédents de migraines), alors que la MAMA ne s'applique qu'en post-partum avec allaitement exclusif.\\n\\nSource : Cours SR/PF L2 — Chap. 14 : Indications du dispositif intra-utérin (DIU).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans quelle situation exceptionnelle le professionnel de santé est-il éthiquement et légalement amené à lever le secret médical concernant un(e) adolescent(e) ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Chaque fois que l'adolescent a une activité sexuelle avant 18 ans.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"En cas de danger immédiat pour la sécurité ou l'intégrité physique ou psychologique du mineur.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Lorsque les parents exigent de connaître le motif exact de la consultation.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Dès que l'adolescent refuse de dire ce qu'il a fait le week-end.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. En cas de danger immédiat pour la sécurité ou l'intégrité physique ou psychologique du mineur.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les adolescents ont droit au respect strict de la confidentialité en consultation de santé sexuelle et reproductive ; la dérogation au secret médical n'est justifiée qu'en cas de danger immédiat et grave pour la sécurité ou l'intégrité physique ou psychologique du mineur (violences, maltraitance, abus sexuels, risque vital).\\n\\nSource : Cours SR/PF L2 — Chap. 17 : Santé sexuelle et reproductive des adolescents (confidentialité).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'outils de travail en planification familiale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le carnet de commande\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les fiches\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La carte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Les fiches\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les fiches (fiches individuelles de consultation, fiches de suivi, fiches techniques) représentent l'outil clinique de base du prestataire lors de la consultation et du suivi en planification familiale, tandis que le carnet de commande est un outil de gestion logistique.\\n\\nSource : Cours SR/PF L2 — Chap. 7 & 18 : Outils de consultation et gestion d'un centre de PF.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la méthode de BILLINGS, après l'ovulation la couleur de la glaire cervicale est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Trouble\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mitigée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mélangée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Claire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Trouble\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la méthode de l'ovulation de Billings, la glaire cervicale est claire, abondante, filante et glissante en période pré-ovulatoire et ovulatoire sous l'effet des œstrogènes ; après l'ovulation, sous l'influence de la progestérone, elle devient rare, épaisse, collante et trouble.\\n\\nSource : Cours SR/PF L2 — Chap. 8 : Méthodes d'auto-observation (méthode de Billings) (p. 28).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cocher deux caractéristiques différenciant le CIC de Sayana Press\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contraceptif\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sous cutané\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Progestérone\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"intra dermique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Intra musculaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Sous cutané ; E. Intra musculaire\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Les contraceptifs injectables combinés (CIC) s'administrent par voie intramusculaire (IM), tandis que le Sayana Press (acétate de médroxyprogestérone retard en dispositif Uniject) s'administre par voie souscutanée (SC) ; ces deux voies d'administration distinctes permettent de les différencier.\\n\\nSource : Cours SR/PF L2 — Chap. 12 & 13 : Contraceptifs injectables (CIC et Sayana Press).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'implant est contre indiqué chez\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La pauci pare\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La nullipare\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La ménopausée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La ménopausée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'implant sous-cutané est utilisable sans restriction (catégorie 1) chez la nullipare comme chez la paucipare ; chez la femme ménopausée, l'arrêt définitif de la fonction ovarienne rend toute contraception inutile et non indiquée.\\n\\nSource : Cours SR/PF L2 — Chap. 13 : Indications et contre-indications des implants.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__52\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente de 26 ans, porteuse d'un dispositif intra-utérin au lévonorgestrel depuis huit mois, consulte car elle n'a plus ses règles du tout depuis 4 mois. Elle s'inquiète d'une possible grossesse ou d'une pathologie.\",\n       \"text\": \"Quel est votre premier diagnostic ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ménopause précoce iatrogène\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Echec de la contraception\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Aménorrhée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"grossesse extra utérine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Aménorrhée\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'absence totale de règles (aménorrhée) est un effet secondaire fréquent, bénin et attendu du système intra-utérin au lévonorgestrel (SIU-LNG), dû à la mise au repos et à l'atrophie réversible de l'endomètre sous l'action locale du progestatif.\\n\\nSource : Cours SR/PF L2 — Chap. 13 & 14 : Effets secondaires des progestatifs et du SIU au lévonorgestrel.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__53\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Une patiente de 26 ans, porteuse d'un dispositif intra-utérin au lévonorgestrel depuis huit mois, consulte car elle n'a plus ses règles du tout depuis 4 mois. Elle s'inquiète d'une possible grossesse ou d'une pathologie.\",\n       \"text\": \"Quelle est l'attitude du prestataire face à la patiente ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Rassurer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Retirer le dispositif intra utérin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réaliser un curetage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Rassurer\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Après avoir écarté une grossesse par l'interrogatoire et l'examen clinique, le prestataire doit rassurer la patiente en lui expliquant que l'aménorrhée sous DIU hormonal est sans danger pour sa santé ni sa fertilité future, et ne nécessite pas le retrait du dispositif.\\n\\nSource : Cours SR/PF L2 — Conduite à tenir devant une aménorrhée sous contraceptif progestatif.\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ssrpf-j4-sfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Cochez la qualité morale d'un bon conseiller\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Comprend les avantages de toutes les méthodes contraceptives\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Comprend les facteurs qui influencent le choix d'une méthode\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Encourage le client à poser des questions\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Encourage le client à poser des questions\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les propositions a et b relèvent des connaissances techniques du prestataire, tandis qu'encourager le client à poser des questions traduit une qualité morale et relationnelle (ouverture, empathie, respect du client) indispensable au bon counseling.\\n\\nSource : Cours SR/PF L2 — Chap. 6 : Qualités morales nécessaires pour un bon counseling (p. 21).\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J4 SSR/PF SFM)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
